-- Phase 3: Document Generator and Compliance Calendar. Run after migration 009.
BEGIN;
CREATE OR REPLACE FUNCTION public.can_manage_documents(p_org UUID) RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.organisation_memberships m WHERE m.organisation_id=p_org AND m.user_id=auth.uid() AND m.is_active AND m.role IN('Organisation Owner','Privacy Admin','Privacy Lead','Legal Reviewer')); $$;
CREATE OR REPLACE FUNCTION public.can_manage_calendar(p_org UUID) RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.organisation_memberships m WHERE m.organisation_id=p_org AND m.user_id=auth.uid() AND m.is_active AND m.role IN('Organisation Owner','Privacy Admin','Privacy Lead','Legal Reviewer','Security Lead','Department Owner')); $$;
REVOKE ALL ON FUNCTION public.can_manage_documents(UUID),public.can_manage_calendar(UUID) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_manage_documents(UUID),public.can_manage_calendar(UUID) TO authenticated;

CREATE TABLE IF NOT EXISTS public.document_templates(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),slug TEXT NOT NULL UNIQUE,name TEXT NOT NULL UNIQUE,description TEXT NOT NULL,input_schema JSONB NOT NULL CHECK(jsonb_typeof(input_schema)='array'),body_template TEXT NOT NULL,is_active BOOLEAN NOT NULL DEFAULT true,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE public.document_templates ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Authenticated users can read document templates" ON public.document_templates;
CREATE POLICY "Authenticated users can read document templates" ON public.document_templates FOR SELECT TO authenticated USING(is_active);

INSERT INTO public.document_templates(slug,name,description,input_schema,body_template) VALUES
('privacy-notice','Privacy Notice','Notice describing personal-data processing','[{"key":"organisation_name","label":"Organisation name","required":true},{"key":"data_categories","label":"Data categories","required":true},{"key":"purposes","label":"Processing purposes","required":true},{"key":"contact","label":"Privacy contact","required":true}]','PRIVACY NOTICE\n\nOrganisation: {{organisation_name}}\n\nData categories\n{{data_categories}}\n\nPurposes\n{{purposes}}\n\nYour rights and contact\nContact {{contact}} to exercise applicable data rights.'),
('consent-notice','Consent Notice','Purpose-specific consent notice','[{"key":"organisation_name","label":"Organisation name","required":true},{"key":"purpose","label":"Consent purpose","required":true},{"key":"data","label":"Data requested","required":true},{"key":"withdrawal","label":"Withdrawal method","required":true}]','CONSENT NOTICE\n\n{{organisation_name}} requests consent for {{purpose}}.\n\nData: {{data}}\n\nWithdrawal: {{withdrawal}}'),
('employee-privacy-notice','Employee Privacy Notice','Workforce privacy notice','[{"key":"organisation_name","label":"Organisation name","required":true},{"key":"employee_data","label":"Employee data","required":true},{"key":"hr_contact","label":"HR/privacy contact","required":true}]','EMPLOYEE PRIVACY NOTICE\n\n{{organisation_name}} processes the following workforce data: {{employee_data}}.\n\nContact: {{hr_contact}}'),
('incident-response-policy','Incident Response Policy','Personal-data incident policy','[{"key":"organisation_name","label":"Organisation name","required":true},{"key":"response_team","label":"Response team","required":true},{"key":"escalation","label":"Escalation process","required":true}]','INCIDENT RESPONSE POLICY\n\nOrganisation: {{organisation_name}}\nResponse team: {{response_team}}\nEscalation: {{escalation}}'),
('rights-request-procedure','Rights Request Procedure','Data Principal request procedure','[{"key":"organisation_name","label":"Organisation name","required":true},{"key":"intake_channel","label":"Intake channel","required":true},{"key":"verification","label":"Verification process","required":true}]','RIGHTS REQUEST PROCEDURE\n\n{{organisation_name}} accepts requests through {{intake_channel}}.\nVerification: {{verification}}'),
('vendor-assessment-checklist','Vendor Assessment Checklist','Processor due-diligence checklist','[{"key":"vendor_name","label":"Vendor name","required":true},{"key":"service","label":"Service","required":true},{"key":"data_categories","label":"Data categories","required":true}]','VENDOR ASSESSMENT CHECKLIST\n\nVendor: {{vendor_name}}\nService: {{service}}\nData: {{data_categories}}\n\n[ ] Security reviewed\n[ ] Privacy terms reviewed\n[ ] DPA approved'),
('data-retention-policy','Data Retention Policy','Retention and deletion policy','[{"key":"organisation_name","label":"Organisation name","required":true},{"key":"retention_schedule","label":"Retention schedule","required":true},{"key":"deletion_process","label":"Deletion process","required":true}]','DATA RETENTION POLICY\n\n{{organisation_name}} retention schedule:\n{{retention_schedule}}\n\nDeletion process:\n{{deletion_process}}'),
('readiness-report','Readiness Report','DPDP readiness summary','[{"key":"organisation_name","label":"Organisation name","required":true},{"key":"score","label":"Readiness score","required":true},{"key":"findings","label":"Key findings","required":true},{"key":"actions","label":"Priority actions","required":true}]','READINESS REPORT\n\nOrganisation: {{organisation_name}}\nScore: {{score}}\n\nFindings\n{{findings}}\n\nPriority actions\n{{actions}}')
ON CONFLICT(slug) DO UPDATE SET name=EXCLUDED.name,description=EXCLUDED.description,input_schema=EXCLUDED.input_schema,body_template=EXCLUDED.body_template,is_active=true;

CREATE TABLE IF NOT EXISTS public.generated_documents(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organisation_id UUID NOT NULL REFERENCES public.organisations(id) ON DELETE CASCADE,template_id UUID NOT NULL REFERENCES public.document_templates(id),title TEXT NOT NULL CHECK(length(btrim(title)) BETWEEN 3 AND 200),input_data JSONB NOT NULL CHECK(jsonb_typeof(input_data)='object'),content TEXT NOT NULL CHECK(length(btrim(content))>=10),status TEXT NOT NULL DEFAULT'Draft' CHECK(status IN('Draft','In Review','Approved','Archived')),current_version INTEGER NOT NULL DEFAULT 1 CHECK(current_version>0),reviewer_user_id UUID REFERENCES auth.users(id),approver_user_id UUID REFERENCES auth.users(id),approved_at TIMESTAMPTZ,created_by UUID NOT NULL REFERENCES auth.users(id),updated_by UUID NOT NULL REFERENCES auth.users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(organisation_id,id));
CREATE TABLE IF NOT EXISTS public.document_versions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organisation_id UUID NOT NULL REFERENCES public.organisations(id) ON DELETE CASCADE,document_id UUID NOT NULL,version_number INTEGER NOT NULL,content TEXT NOT NULL,input_data JSONB NOT NULL,status TEXT NOT NULL,created_by UUID NOT NULL REFERENCES auth.users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(organisation_id,document_id,version_number),CONSTRAINT document_version_same_org_fk FOREIGN KEY(organisation_id,document_id) REFERENCES public.generated_documents(organisation_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS public.document_comments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organisation_id UUID NOT NULL REFERENCES public.organisations(id) ON DELETE CASCADE,document_id UUID NOT NULL,comment_text TEXT NOT NULL CHECK(length(btrim(comment_text)) BETWEEN 1 AND 2000),created_by UUID NOT NULL REFERENCES auth.users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CONSTRAINT document_comment_same_org_fk FOREIGN KEY(organisation_id,document_id) REFERENCES public.generated_documents(organisation_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS public.document_record_links(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organisation_id UUID NOT NULL REFERENCES public.organisations(id) ON DELETE CASCADE,document_id UUID NOT NULL,related_module TEXT NOT NULL CHECK(length(related_module) BETWEEN 2 AND 80),related_record_id TEXT NOT NULL CHECK(length(related_record_id) BETWEEN 1 AND 200),created_by UUID NOT NULL REFERENCES auth.users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(organisation_id,document_id,related_module,related_record_id),CONSTRAINT document_link_same_org_fk FOREIGN KEY(organisation_id,document_id) REFERENCES public.generated_documents(organisation_id,id) ON DELETE CASCADE);

CREATE TABLE IF NOT EXISTS public.compliance_tasks(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organisation_id UUID NOT NULL REFERENCES public.organisations(id) ON DELETE CASCADE,title TEXT NOT NULL CHECK(length(btrim(title)) BETWEEN 3 AND 180),description TEXT CHECK(length(description)<=3000),owner_name TEXT CHECK(length(owner_name)<=120),category TEXT NOT NULL CHECK(category IN('Rights Request','Vendor Review','Contract Expiry','Policy Review','Consent Review','Retention Cleanup','Incident Drill','Assessment Review','DPO/VDPO Report','Other')),priority TEXT NOT NULL DEFAULT'Medium' CHECK(priority IN('Low','Medium','High','Critical')),start_date DATE NOT NULL,due_date DATE NOT NULL,status TEXT NOT NULL DEFAULT'Open' CHECK(status IN('Open','In Progress','Completed','Cancelled')),recurrence TEXT NOT NULL DEFAULT'None' CHECK(recurrence IN('None','Daily','Weekly','Monthly','Quarterly','Yearly')),reminder_at TIMESTAMPTZ,related_module TEXT,related_record_id TEXT,completed_at TIMESTAMPTZ,created_by UUID NOT NULL REFERENCES auth.users(id),updated_by UUID NOT NULL REFERENCES auth.users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(due_date>=start_date),UNIQUE(organisation_id,id));
CREATE TABLE IF NOT EXISTS public.calendar_task_evidence(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),organisation_id UUID NOT NULL REFERENCES public.organisations(id) ON DELETE CASCADE,task_id UUID NOT NULL,evidence_name TEXT NOT NULL CHECK(length(btrim(evidence_name)) BETWEEN 2 AND 200),evidence_url TEXT CHECK(evidence_url IS NULL OR evidence_url ~* '^https://'),notes TEXT CHECK(length(notes)<=1000),created_by UUID NOT NULL REFERENCES auth.users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CONSTRAINT calendar_evidence_same_org_fk FOREIGN KEY(organisation_id,task_id) REFERENCES public.compliance_tasks(organisation_id,id) ON DELETE CASCADE);

DO $$ DECLARE t TEXT;fn TEXT;BEGIN FOR t,fn IN SELECT * FROM(VALUES('generated_documents','can_manage_documents'),('document_versions','can_manage_documents'),('document_comments','can_manage_documents'),('document_record_links','can_manage_documents'),('compliance_tasks','can_manage_calendar'),('calendar_task_evidence','can_manage_calendar'))v(t,f) LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('DROP POLICY IF EXISTS "Members read %s" ON public.%I',t,t);EXECUTE format('DROP POLICY IF EXISTS "Managers create %s" ON public.%I',t,t);EXECUTE format('DROP POLICY IF EXISTS "Managers update %s" ON public.%I',t,t);EXECUTE format('DROP POLICY IF EXISTS "Managers delete %s" ON public.%I',t,t);EXECUTE format('CREATE POLICY "Members read %s" ON public.%I FOR SELECT TO authenticated USING(public.is_active_org_member(organisation_id))',t,t);EXECUTE format('CREATE POLICY "Managers create %s" ON public.%I FOR INSERT TO authenticated WITH CHECK(public.%I(organisation_id))',t,t,fn);IF t NOT IN('document_versions')THEN EXECUTE format('CREATE POLICY "Managers update %s" ON public.%I FOR UPDATE TO authenticated USING(public.%I(organisation_id)) WITH CHECK(public.%I(organisation_id))',t,t,fn,fn);END IF;EXECUTE format('CREATE POLICY "Managers delete %s" ON public.%I FOR DELETE TO authenticated USING(public.%I(organisation_id))',t,t,fn);END LOOP;END $$;
DO $$ DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['generated_documents','document_comments','document_record_links','compliance_tasks','calendar_task_evidence'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS prevent_%s_org_change ON public.%I',t,t);EXECUTE format('CREATE TRIGGER prevent_%s_org_change BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.prevent_organisation_id_change()',t,t);END LOOP;FOREACH t IN ARRAY ARRAY['generated_documents','document_versions','document_comments','document_record_links','compliance_tasks','calendar_task_evidence'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS audit_%s_changes ON public.%I',t,t);EXECUTE format('CREATE TRIGGER audit_%s_changes AFTER INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.audit_privacy_operation()',t,t);END LOOP;END $$;
CREATE INDEX IF NOT EXISTS idx_documents_org_status ON public.generated_documents(organisation_id,status,updated_at DESC);CREATE INDEX IF NOT EXISTS idx_tasks_org_due ON public.compliance_tasks(organisation_id,due_date,status);
COMMIT;
-- Read-only verification.
SELECT c.relname,c.relrowsecurity,count(p.policyname) policy_count FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_catalog.pg_policies p ON p.schemaname=n.nspname AND p.tablename=c.relname WHERE n.nspname='public' AND c.relname IN('generated_documents','document_versions','document_comments','document_record_links','compliance_tasks','calendar_task_evidence')GROUP BY c.relname,c.relrowsecurity ORDER BY c.relname;
